L17_1.m_CharScale = L18_1
L17_1.m_CharScaleTime = 0.01
L17_1.m_Talk_KOREA = "설마, 여기 있는 것들 전부 그 메이시 박사라는 분이 만든 걸까요?"
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "まさか、ここにあるもの全部、そのメイシ博士っていう人が作ったのかしら？"
L17_1.m_Talk_ENG = "You think all this stuff was made by Dr. Macy?"
