L20_1 = {}
L20_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE3@12#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 607
L20_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE3"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_IDLE"
L20_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L20_1.m_Pos = "R"
L20_1.m_Talk_KOREA = "글쎄다? 할망구 말로는 여기가 그 유명한 퓨처 앳 워 연구소 중 하나라고 했으니까."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "さあ？　ババァはここがあの有名なフューチャーアットウォーの研究所の一つだって言ってたからな。"
L20_1.m_Talk_ENG = "Who knows? The old hag said this was one of the Future-at-War labs."
L20_1.m_Talk_TWN = "誰知道呢？瘋婆子說這裡是著名的天啟兵器研究所之一。"
L20_1.m_Talk_SCN = "谁知道呢？老太婆说这里是著名的天启兵器研究所之一。"
L20_1.m_Talk_DEU = "Who knows? The old hag said this was one of the Future-at-War labs."
L20_1.m_Talk_FRA = "Who knows? The old hag said this was one of the Future-at-War labs."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE3@13#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 607
L21_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE3"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "FELICETTE_CANARY_NULL_NULL"
L21_1.m_Pos = "L"
L21_1.m_Talk_KOREA = "퓨처 앳 워라면 엄마한테 들은 적이 있어요."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "フューチャーアットウォーなら、お母さんから聞いたことがあるわ。"
L21_1.m_Talk_ENG = "Future-at-War? Oh, I've heard of that. My mom used to talk about it."
L21_1.m_Talk_TWN = "如果是天啟兵器，我聽媽媽說過。"
L21_1.m_Talk_SCN = "如果是天启兵器，我听妈妈说过。"
L21_1.m_Talk_DEU = "Future-at-War? Oh, I've heard of that. My mom used to talk about it."
L21_1.m_Talk_FRA = "Future-at-War? Oh, I've heard of that. My mom used to talk about it."
L22_1 = {}
L22_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE3@14#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 607
L22_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE3"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "FELICETTE_CANARY_NULL_NULL"
L22_1.m_Pos = "L"
L22_1.m_Talk_KOREA = "여긴 천재 중의 천재만 입사할 수 있는 곳이라면서요?"
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "天才の中の天才しか入社できないところだって。"
L22_1.m_Talk_ENG = "Only super-geniuses are allowed to work here, right?"
L22_1.m_Talk_TWN = "這裡不是說只有天才中的天才能入職嗎？"
L22_1.m_Talk_SCN = "这里不是说只有天才中的天才能入职吗？"
L22_1.m_Talk_DEU = "Only super-geniuses are allowed to work here, right?"
L22_1.m_Talk_FRA = "Only super-geniuses are allowed to work here, right?"
L23_1 = {}
L23_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE3@15#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 607
L23_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE3"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_SERIOUS"
L23_1.m_CharStrID = "FELICETTE_CANARY_NULL_NULL"
L23_1.m_Pos = "L"
L23_1.m_Talk_KOREA = "이런 커다란 연구소의 소장이라면, 틀림없이 라이카보다 백배는 더 똑똑하겠죠?"
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "こんな大きな研究所の所長なら、きっとライカより100倍は頭がいいんだろうね？"
L23_1.m_Talk_ENG = "If she's the head of such a huge lab, she's gotta be a hundred times smarter than you. Right, Laika?"
L23_1.m_Talk_TWN = "如果是這樣一個大型研究所的所長，肯定比萊卡聰明百倍吧？"
L23_1.m_Talk_SCN = "如果是这样一个大型研究所的所长，肯定比莱卡聪明百倍吧？"
L23_1.m_Talk_DEU = "If she's the head of such a huge lab, she's gotta be a hundred times smarter than you. Right, Laika?"
L23_1.m_Talk_FRA = "If she's the head of such a huge lab, she's gotta be a hundred times smarter than you. Right, Laika?"
L24_1 = {}
L24_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE3@16#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 607
L24_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE3"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_IDLE"
L24_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L24_1.m_Pos = "R"
L24_1.m_Talk_KOREA = "그래? 내가 들은 거랑 조금 다른데?"
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "どうだろうな。それに、私が聞いたのとはちょっと違うしね。"
L24_1.m_Talk_ENG = "Eh, that's not what I heard."
L24_1.m_Talk_TWN = "是嗎？和我聽到的有點不一樣呢？"
L24_1.m_Talk_SCN = "是吗？和我听到的有点不一样呢？"
L24_1.m_Talk_DEU = "Eh, that's not what I heard."
L24_1.m_Talk_FRA = "Eh, that's not what I heard."
L25_1 = {}
L25_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE3@17#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 607
L25_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE3"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L25_1.m_Pos = "R"
L25_1.m_Talk_KOREA = "무인 전쟁을 추구했던 초창기 퓨처 앳 워 계획은 진즉에 실패해 버렸고."
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "無人戦争を追及していた初期のフューチャーアットウォー計画はとっくに失敗してて。"
L25_1.m_Talk_ENG = "The original Future-at-War program for unmanned combat failed ages ago."
L25_1.m_Talk_TWN = "追求無人戰爭的初期天啟兵器計畫早就失敗了。"
L25_1.m_Talk_SCN = "追求无人战争的初期天启兵器计划早已失败了。"
L25_1.m_Talk_DEU = "The original Future-at-War program for unmanned combat failed ages ago."
L25_1.m_Talk_FRA = "The original Future-at-War program for unmanned combat failed ages ago."
L26_1 = {}
L26_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE3@18#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 607
L26_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE3"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L26_1.m_Pos = "R"
L26_1.m_Talk_KOREA = "지금까지 퓨처 앳 워에 남아있는 녀석들은 괴짜 중의 괴짜들 밖에 없다고 들었거든."
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "まだフューチャーアットウォーに残ってるやつらは変人の中の変人しかいないって話だった。"
L26_1.m_Talk_ENG = "The ones still hanging around there are all weirdos among weirdos."
L26_1.m_Talk_TWN = "我聽說現在留在天啟兵器中的傢伙都是怪胎中的怪胎。"
L26_1.m_Talk_SCN = "我听说现在留在天启兵器中的家伙都是怪胎中的怪胎。"
L26_1.m_Talk_DEU = "The ones still hanging around there are all weirdos among weirdos."
L26_1.m_Talk_FRA = "The ones still hanging around there are all weirdos among weirdos."
