L29_1.m_Talk_KOREA = "그래, 그 메이시 박사라는 녀석도 사실은 엄청난 괴짜일지도 모르지."
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "ああ、そのメイシ博士ってやつも実はものすごい変人かもよ。"
L29_1.m_Talk_ENG = "Yeah. For all we know, Dr. Macy could be one too."
L29_1.m_Talk_TWN = "是啊，說不定那個叫梅西的博士其實是個超級怪胎呢。"
L29_1.m_Talk_SCN = "是啊，说不定那个叫梅西的博士其实是个超级怪胎呢。"
L29_1.m_Talk_DEU = "Yeah. For all we know, Dr. Macy could be one too."
L29_1.m_Talk_FRA = "Yeah. For all we know, Dr. Macy could be one too."
