L30_1.m_Talk_KOREA = "아니, 어쩌면 터질듯한 근육질 몸매에 수염 잔뜩 난 술고래 영감탱이일지도 몰라."
L30_1.m_fTalkTime = 0.03
L30_1.m_Talk_JPN = "いや、もしかしたら弾けるばかりのマッチョなボディにヒゲ面の酔っ払いジジィかも。"
L30_1.m_Talk_ENG = "Or worse, some musclehead drunk with a beard."
