L35_1 = "DOCTOR_MAIN_NPC_NULL"
L34_1.m_CharStrID = L35_1
L35_1 = "기본적으로 콜드 케이스라는 건, 특정 아티팩트의 분류명이라고 할 수 있어."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "基本的にコールドケースというのは、特定のアーティファクトの分類名とも言えるの。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Basically, Cold Cases are classification tags for specific Artifacts."
