L36_1 = "DOCTOR_MAIN_NPC_NULL"
L35_1.m_CharStrID = L36_1
L36_1 = "왜냐하면 그건 고도의 과학 기술을 보유했던 <color=#ffd34c>어떤 세계</color>로부터 전해진 유산이거든."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "あれは高度の科学技術を保有していた<color=#ffd34c>ある世界</color>から伝わった遺産だからね。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "This one was passed down from a <color=#ffd34c>certain world</color> with highly advanced technology."
L35_1.m_Talk_ENG = L36_1
L36_1 = "因為那是從擁有高度科學技術的<color=#ffd34c>某個世界</color>傳下來的遺產。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "因为那是从拥有高度科学技术的<color=#ffd34c>某个世界</color>传下来的遗产。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "This one was passed down from a <color=#ffd34c>certain world</color> with highly advanced technology."
L35_1.m_Talk_DEU = L36_1
L36_1 = "This one was passed down from a <color=#ffd34c>certain world</color> with highly advanced technology."
L35_1.m_Talk_FRA = L36_1
