L32_1 = "DOCTOR_MAIN_NPC_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "L"
L32_1 = "이 제어장치는 충격에 예민하기 때문에 충격량이 누적해서 쌓이면 과부하가 걸려."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "この制御装置は衝撃に敏感で、衝撃量が累積して溜まると過負荷がかかるわ。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "But it's sensitive to impact. If too much shock builds up, it could overload."
L31_1.m_Talk_ENG = L32_1
L32_1 = "這個控制裝置對衝擊非常敏感，因此如果衝擊量累積起來，就會導致超載。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "这个控制装置对冲击非常敏感，因此如果冲击量累积起来，就会导致过载。"
L31_1.m_Talk_SCN = L32_1
