L28_1 = "우리가 연구자도 아니고, 고작 아티팩트의 이름 가지고 어떻게 그런 걸 떠올리라는 거야?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "研究者でもないのに、アーティファクトの名前だけでどうやって思いつけっていうんだよ。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "We're not researchers. So how are we supposed to know something like that from just the Artifact name?"
