L39_1 = "당시 퓨처 앳 워는 88번이 무언가를 관측하는 장치라고 추측하고 있었으니까."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "当時フューチャーアットウォーはNo.88が何かを観測するための装置だと推測してたからね。"
L38_1.m_Talk_JPN = L39_1
