L44_1.m_Pos = "L"
L45_1 = "관측 장비라면, 그걸로 뭘 관측하는 건가요?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "観測装置というなら、それで何を観測するんですか？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "If it's an observation device, what exactly is it meant to observe?"
L44_1.m_Talk_ENG = L45_1
L45_1 = "觀測設備的話，是用來觀測什麼的呢？"
