L47_1 = 396
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 607
L46_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE3"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
