L47_1 = "DOCTOR_MAIN_NPC_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "C"
L47_1 = "간단해. 망원 렌즈라는 건, 물리적인 에너지의 흐름을 바꾸는 제어 장치거든."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "簡単よ。望遠レンズというものは、物理的なエネルギーの流れを変える制御装置。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "It's simple. The Zoom Lens is a control device that redirects the flow of physical energy."
L46_1.m_Talk_ENG = L47_1
L47_1 = "很簡單。所謂的望遠鏡頭，就是改變物理能量流動的控制裝置。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "很简单。所谓的望远镜头，就是改变物理能量流动的控制装置。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "It's simple. The Zoom Lens is a control device that redirects the flow of physical energy."
L46_1.m_Talk_DEU = L47_1
L47_1 = "It's simple. The Zoom Lens is a control device that redirects the flow of physical energy."
L46_1.m_Talk_FRA = L47_1
