L47_1.m_Pos = "C"
L48_1 = "하지만 반대로 물리 에너지가 아닌, 특별한 타입의 에너지에는 간섭할 수 없어."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "でも逆に物理エネルギーではなく、特別なタイプのエネルギーには干渉できないわ。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "But on the other hand, it can't interfere with special types of energy that are not physical energy."
