L48_1.m_Pos = "C"
L49_1 = "그리고 간섭할 수 없기 때문에, 일방적으로 에너지 파장을 그대로 투과해 버리지."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "干渉できないから、一方的にエネルギーの波長をそのまま透過させてしまう。"
